// WPForm 29710 field-id mapping → semantic names + idempotency hash
// See build plan §3 (form 29710 column)
const raw = $json.body || $json;
const crypto = require('crypto');
const entryId = String(raw.entry_id || raw.entry?.entry_id || raw.id || '');
const hash = crypto.createHash('sha256').update(`29710:${entryId}`).digest('hex');
return [{ json: {
  source: 'wpform_29710',
  WPFormName: 'ContactForm',
  wpformsEntryId: entryId,
  Idempotency_Hash__c: hash,
  Received_At__c: new Date().toISOString(),
  Payload__c: JSON.stringify(raw).substring(0, 32000),
  // semantic field map
  BusinessEmail: raw.fields?.['13'] || raw.field13 || '',
  FirstName:     raw.fields?.['2']  || raw.field2  || '',
  LastName:      raw.fields?.['3']  || raw.field3  || '',
  CompanyName:   raw.fields?.['5']  || raw.field5  || '',
  PhoneNumber:   raw.fields?.['7']  || raw.field7  || '',
  YourIndustry:  raw.fields?.['6']  || raw.field6  || '',
  YourRegion:    raw.fields?.['14'] || raw.field14 || '',
  utmSource:     raw.fields?.['8']  || raw.field8  || '',
  utmMedium:     raw.fields?.['9']  || raw.field9  || '',
  utmCampaign:   raw.fields?.['10'] || raw.field10 || '',
  utmTerm:       raw.fields?.['11'] || raw.field11 || '',
  utmContent:    raw.fields?.['12'] || raw.field12 || '',
  gclid:         raw.fields?.['17'] || raw.field17 || '',
  fbc:           raw.fields?.['18'] || raw.field18 || '',
  fbp:           raw.fields?.['19'] || raw.field19 || '',
  msclkid:       raw.fields?.['20'] || raw.field20 || '',
  ROIcalculator: raw.fields?.['26'] || raw.field26 || ''
} }];
